#include <linux/platform_device.h>
#include <linux/mailbox/client.h>
#include <linux/clk-provider.h>
#include <linux/io.h>
#include <linux/slab.h>

int hi3660_stub_clk_probe(struct platform_device *pdev)
{
    struct mbox_client *cl;
    struct mbox_client *chan;
    void __iomem *regs;
    struct clk_hw **hws;
    int num_clocks = 8; // Example number of stub clocks
    int ret;

    cl = devm_kzalloc(&pdev->dev, sizeof(*cl), GFP_KERNEL);
    if (!cl)
        return -ENOMEM;

    cl->dev = &pdev->dev;
    cl->tx_done = NULL;
    cl->tx_prepare = NULL;
    cl->rx_callback = NULL;
    cl->tx_block = false;

    chan = mbox_request_channel(cl, NULL);
    if (IS_ERR(chan)) {
        dev_err(&pdev->dev, "Failed to request mailbox channel\n");
        return PTR_ERR(chan);
    }

    regs = platform_get_drvdata(pdev);
    if (!regs) {
        dev_err(&pdev->dev, "Failed to get memory resource\n");
        ret = -ENOMEM;
        goto err_free_channel;
    }

    hws = devm_kzalloc(&pdev->dev, num_clocks * sizeof(struct clk_hw *), GFP_KERNEL);
    if (!hws) {
        ret = -ENOMEM;
        goto err_free_channel;
    }

    ret = hi3660_register_stubs(&pdev->dev, hws, num_clocks, regs);
    if (ret) {
        dev_err(&pdev->dev, "Failed to register clock hardware\n");
        goto err_free_hws;
    }

    ret = of_clk_add_provider(pdev->dev.of_node, of_clk_src_onecell_get, hws);
    if (ret) {
        dev_err(&pdev->dev, "Failed to add clock provider\n");
        goto err_unregister_clocks;
    }

    return 0;

err_unregister_clocks:
    hi3660_unregister_stubs(hws, num_clocks);
err_free_hws:
    devm_kfree(&pdev->dev, hws);
err_free_channel:
    mbox_free_channel(chan);
    return ret;
}
